-- GENERATED by `wfj generate` from data/gossip/gossip-c3.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["c308ab067cdc8ff0"] = { "Il tempo sta per scadere per me... per tutti noi...", "." },
  ["c311f1a3180a81b0"] = { "%s si dissolve davanti ai tuoi occhi.", "." },
  ["c316bf425049b5c0"] = { "Abbiamo a malapena rifornimenti in eccesso. Ci vorrà molto altro lavoro prima di poter lanciare un altro assalto via terra nel ⟦Field of Strife=Pian della Discordia⟧.", "." },
  ["c31b7bf4f1c91132"] = { "Giusto in tempo, {class}. Senti la terra che trema sotto i piedi?\n\nQualcosa si avvicina dall'alveare. Prendi posizione vicino ai grunt, {name}. Conto su di te!", "." },
  ["c31ba0206997519e"] = { "Qualche anno fa tutte le isole del cielo hanno perso stabilità e hanno cominciato ad allontanarsi l'una dall'altra. Come se non bastasse, ora grossi pezzi di Zephras cominciano a staccarsi. È difficile immaginare la propria casa che precipita nel cielo, ma ora questa è la mia realtà.", "." },
  ["c3223e2319ad1132"] = { "Ce l'hai fatta, {name}! <La voce stranamente familiare sembra provenire dalla fiala!> Torna in fretta! Il materiale resterà stabile solo per trenta minuti.", "." },
  ["c324373f171ea9e0"] = { "Non fare <il/la> <timido/timida>, offri un giro a tutti!", "." },
  ["c3264340cee9273d"] = { "Hanno messo fuori queste lanterne per celebrare la chiusura della Celebrazione della Luna.", "." },
  ["c328062ec442bb77"] = { "Tutte quelle pratiche ufficiali oggi si sbrigano su a ⟦Stormwind=Roccavento⟧. Se vuoi fondare una gilda, puoi passare dal Visitor's Center di ⟦Stormwind=Roccavento⟧.", "." },
  ["c329852fc9348f4e"] = { "Le tue azioni ci disonorano tutti, {class}. Mi fa male dentro mentre ti pesto fino a farti perdere i sensi.", "." },
  ["c3328051190793da"] = { "{name} ha catturato la bandiera dell'⟦Horde=Orda⟧!", "." },
  ["c342b500b6a5b0f7"] = { "Tremate davanti alla nostra potenza! Fuggite! Non ci sarà vittoria per i vivi!", "." },
  ["c347cd865b1800ec"] = { "Se hai sentito che tutte le raccolte dell'⟦Horde=Orda⟧ e dell'⟦Alliance=Alleanza⟧ sono state completate, hai sentito bene, {class}. Tutti i beni per la guerra che abbiamo raccolto e preparato stanno per essere spediti alla ⟦Cenarion Hold=Fortezza Cenariana⟧, a ⟦Silithus=Silitus⟧, e mancano meno di $2113w giorni all'arrivo dell'ultimo carico. Dopo, immagino che non ci resterà che aspettare e vedere chi ricomporrà quello scettro per suonare il gong, che aprirà le porte di ⟦Ahn'Qiraj=Ahn'qiraj⟧ e darà inizio alla guerra.", "." },
  ["c34826b5693b6826"] = { "Non profanerai questi misteri!", "." },
  ["c351681e37980b04"] = { "Il maestro dei grifoni più vicino si trova su a ⟦Ironforge=Forgiardente⟧, proprio vicino alla ⟦Great Forge=Grande Forgia⟧. Dovrai andare a ⟦Ironforge=Forgiardente⟧ se vuoi viaggiare in grifone.", "." },
  ["c353b5af7f17cd2e"] = { "Ora, dove ho messo quel documento di accompagnamento?", "." },
  ["c35b3865f2ffdaaf"] = { "Fuggi finché puoi, mortale!", "." },
  ["c361e519a976598c"] = { "%s bacia il suo amato.", "." },
  ["c36376a92a5bb2d5"] = { "Quando le nostre scorte sono abbondanti, il maestro di guerra Garrick è di stanza nel ⟦Field of Strife=Pian della Discordia⟧ presso una catapulta, a nord del ⟦Iceblood Garrison=Presidio di Brinarossa⟧.", "." },
  ["c367032c28cf22d0"] = { "Somministro pugni di furia a {name}!", "." },
  ["c3747434c50fe805"] = { "Si narra di un'unica, leggendaria lama di Quel'Serrar forgiata per un'entità sconosciuta dalla forza congiunta dei cinque Aspetti. Prima che gli abomini di Nefarian e di Alamorte venissero scagliati nel nostro mondo, simili riunioni degli Aspetti erano indicate con il termine 'Prismatico'. Potevo solo supporre che la Lama Prismatica di Quel'Serrar fosse una creazione gloriosissima.", "." },
  ["c378eeb7add1e52f"] = { "Non avere paura; siamo qui per aiutarti. Ti siamo grati per la difesa che ci hai offerto nella nostra antica dimora e, in segno di ringraziamento, siamo venuti ad aiutarti a tornare rapidamente nelle ⟦Plaguelands=Terre Infette⟧, se dovesse servirti. Il mio compagno può spiegarti meglio come funziona; lo troverai dove le energie arcane sono più forti in questa città.", "." },
  ["c3798aa00d8673e9"] = { "La morte arriva! Gioite!", "." },
  ["c37c49ce85d92fb4"] = { "Come si fonda una gilda?", "." },
  ["c380508e1674aabd"] = { "Devi avere reputazione Amichevole con gli orchi di Orgrimmar prima che ti insegni a cavalcare, {class}.", "." },
  ["c388fe06ab769513"] = { "Sono là fuori! Li sento di notte, che ridono. Oh, la pagheranno! La... pagheranno... cara!!", "." },
  ["c392ca5a312a1f8d"] = { "Naralex dorme di nuovo!\n\nTanto tempo fa, Naralex giunse in questa caverna con il nobile scopo di entrare nel ⟦Emerald Dream=Sogno di Smeraldo⟧ e far rinascere le ⟦Barrens=Savane⟧ come una rigogliosa foresta. Ma la sua concentrazione vacillò e i suoi pensieri furono contaminati da visioni serpentine.\n\nOra, dai suoi sogni, bestie rettili filtrano nel mondo. Bisogna svegliarlo dall'incubo, o sarà perduto per sempre e un grande male verrà scatenato.\n\nSolo dopo che i suoi servitori corrotti, i Fanglord, saranno stati uccisi potrò celebrare il rituale del risveglio.", "." },
  ["c39768847a3ce90e"] = { "Per la Luce, che fame oggi. Avete visto Darcy oggi? Era splendida.", "." },
  ["c39e136bba5b9ac9"] = { "Comandante, è giunto il momento di caricare la feccia dei Lupi Bianchi! Trafiggeteli!", "." },
  ["c3a64189fe801be0"] = { "%s e l'incursore Kerr lasciano riposare e bere un po' i loro lupi...", "." },
  ["c3a8fa7e07ef3dc4"] = { "%s si attiva!", "." },
  ["c3aca745f88e50e0"] = { "A nome della Società Reale degli Speziali, ho il piacere di offrirti i migliori destrieri disponibili per i Reietti. Queste bestie hanno sopportato prove e tribolazioni come tutti noi, e ora anche loro ne sono uscite più forti e più resistenti di quanto la semplice carne mortale avrebbe mai concesso loro! Ti prego, esaminale di persona e vedrai.", "." },
  ["c3ad5ff5abadc87b"] = { "Fammi consultare i miei colleghi.", "." },
  ["c3ae3007d53b033c"] = { "%s ascolta il rapporto di {name}...", "." },
  ["c3ae9f4e168ed623"] = { "%s è vuoto.", "." },
  ["c3b06fdacfa2da67"] = { "[PH] Questa è un'azione segnaposto finché non riesco ad annullare la canalizzazione del mio incantesimo.", "." },
  ["c3b52a825a1fc3c3"] = { "Vuoi conoscere la pietra? Seguimi.", "." },
  ["c3ba5ee70ad05e70"] = { "Vendi colonia e profumo?", "." },
  ["c3c236b608ed7ff2"] = { "Con le loro forme manifeste indebolite da eoni di battaglia, prigionieri sotto il mondo, quel mondo che loro stessi avevano creato, la corruzione dei Titani Plasmatori sarebbe filtrata fino in superficie, contaminando gli Dei Antichi.\n\nFu allora e lì che i fratelli si voltarono. Per cinque millenni si combatté una battaglia nel cuore di questo mondo.", "." },
  ["c3d2c7665577e9f4"] = { "L'istruttore di ingegneria di Roccavento è uno gnomo geniale di nome Lilliam Sparkspindle. Lo trovi in fondo al Distretto dei Nani.", "." },
  ["c3da5537d3b76820"] = { "Ottimo lavoro, {name}. Troviamo l'uscita. Credo di conoscere la strada. Seguimi!", "." },
  ["c3e99a4eb93874cb"] = { "Vediamo se stavolta riesco a fare centro.", "." },
  ["c3ea87ba00370380"] = { "A lavorare con le macchine così a lungo, a volte ti dimentichi dei cuori veri.", "." },
  ["c3f310f6fceaeadc"] = { "Il dolce profumo del cibo purificato attira %s allo scoperto.", "." },
  ["c3f3142a693132e9"] = { "Il capofamiglia sono io. Io. IO!!!", "." },
  ["c3f8d5a7f08b707e"] = { "Non sei all'altezza di addestrarti con me, straniero. Passa un po' di tempo con il mio assistente Jhag, laggiù.", "." },
  ["c3f8e2baea461564"] = { "Ah sì, ancora qualcuno che alimenterà i fuochi e forgerà le armi della guerra. Certo che ti insegnerò come si fa.", "." },
})
